window.docContents[122].resolve({"/LindenstraussPolynomials/Construction/#LindenstraussPolynomials___seqM":{"contents":"M_k = ‖P_k‖. \n\n","context":"","header":"LindenstraussPolynomials.seqM","id":"/LindenstraussPolynomials/Construction/#LindenstraussPolynomials___seqM"},"/LindenstraussPolynomials/Construction/#mod-doc-LindenstraussPolynomials___Construction-1-0":{"contents":"The perturbation scheme\n\nStarting from P_0=P, the construction (eq:viteration) sets\nP_{k+1} = P_k + \\alpha_k\\,(\\mathcal R_k p_k)\\,w_k,\\qquad p_k=y_k^*\\circ P_k,\\quad w_k=\\frac{P_k(x_k)}{\\|P_k(x_k)\\|},\nwhere x_k almost norms P_k, f_k is a norming functional of x_k, and y_k^* norms P_k(x_k). Polynomials are represented by their symmetric n-linear forms. The module proves the norm increments (eq:increment) and bounds (eq:normbounds).\n\n\n","context":"","header":"LindenstraussPolynomials.Construction","id":"/LindenstraussPolynomials/Construction/#mod-doc-LindenstraussPolynomials___Construction-1-0"}});